        void ScriptA1Sunday::a1_sunday() {
            if (ks::globals::exit_scenario) return;
            SKIP_IF_LOAD_ANOTHER_SCENE(SCRIPT_A1_SUNDAY);
            ks::SceneManager::set_script(SCRIPT_A1_SUNDAY);
            ks::SceneManager::init_savedata(ks::progress);
            ks::SceneManager::set(ks::SceneManager("script_a1_sunday"));
        
            if (!ks::progress.force_route) {
                ks::progress.force_route = FR_KENJI;
            }
            ks::SceneManager::timeskip();
            ScriptA1Sunday::a1_sunday_dont_panic(); // INLINE CALL
            if (ks::progress.force_route == FR_EMI) {
                ScriptA1Sunday::a1_sunday_is_carnival(); // INLINE CALL
            }
            if (ks::progress.force_route == FR_RIN) {
                ScriptA1Sunday::a1_sunday_clouds_in_my_head(); // INLINE CALL
            }
            if (ks::progress.force_route == FR_LILLY) {
                ScriptA1Sunday::a1_sunday_promise_of_time(); // INLINE CALL
            }
            if (ks::progress.force_route == FR_HANAKO) {
                ScriptA1Sunday::a1_sunday_nc5xb3(); // INLINE CALL
                ScriptA1Sunday::a1_sunday_movement(); // INLINE CALL
            }
            if (ks::progress.force_route == FR_SHIZU) {
                ScriptA1Sunday::a1_sunday_throwing_balls(); // INLINE CALL
            }
            if (ks::progress.force_route == FR_KENJI) {
                ScriptA1Sunday::a1_sunday_the_deep_end(); // INLINE CALL
            }
        }
